+import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
+import { dirname, resolve } from "node:path";
+
+type Status = "open" | "done";
+
+export interface Task {
+  id: number;
+  title: string;
+  tags: string[];
+  due?: string;
+  status: Status;
+  createdAt: string;
+  completedAt?: string;
+}
+
+interface Database {
+  nextId: number;
+  tasks: Task[];
+}
+
+class UsageError extends Error {}
+
+function isDate(value: string): boolean {
+  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
+  const [year, month, day] = value.split("-").map(Number);
+  const date = new Date(year, month - 1, day);
+  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
+}
+
+function today(): string {
+  const now = new Date();
+  const year = now.getFullYear();
+  const month = String(now.getMonth() + 1).padStart(2, "0");
+  const day = String(now.getDate()).padStart(2, "0");
+  return `${year}-${month}-${day}`;
+}
+
+function normalizeTags(value: string): string[] {
+  return [...new Set(value.split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
+}
+
+function assertDatabase(value: unknown): asserts value is Database {
+  if (!value || typeof value !== "object") throw new UsageError("Malformed database");
+  const database = value as Partial<Database>;
+  if (!Number.isSafeInteger(database.nextId) || database.nextId < 1 || !Array.isArray(database.tasks)) {
+    throw new UsageError("Malformed database");
+  }
+  const ids = new Set<number>();
+  for (const task of database.tasks) {
+    if (!task || typeof task !== "object" || !Number.isSafeInteger(task.id) || task.id < 1 || ids.has(task.id) ||
+      typeof task.title !== "string" || !Array.isArray(task.tags) || !task.tags.every((tag) => typeof tag === "string") ||
+      (task.status !== "open" && task.status !== "done") || typeof task.createdAt !== "string" ||
+      (task.due !== undefined && (!isDate(task.due))) ||
+      (task.completedAt !== undefined && typeof task.completedAt !== "string")) {
+      throw new UsageError("Malformed database");
+    }
+    ids.add(task.id);
+  }
+}
+
+async function loadDatabase(file: string): Promise<Database> {
+  try {
+    const parsed: unknown = JSON.parse(await readFile(file, "utf8"));
+    assertDatabase(parsed);
+    return parsed;
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === "ENOENT") return { nextId: 1, tasks: [] };
+    if (error instanceof UsageError) throw error;
+    throw new UsageError("Malformed database");
+  }
+}
+
+async function saveDatabase(file: string, database: Database): Promise<void> {
+  const directory = dirname(file);
+  await mkdir(directory, { recursive: true });
+  const temporary = `${file}.${process.pid}.${Date.now()}.tmp`;
+  try {
+    await writeFile(temporary, `${JSON.stringify(database, null, 2)}\n`, "utf8");
+    await rename(temporary, file);
+  } catch (error) {
+    await unlink(temporary).catch(() => undefined);
+    throw error;
+  }
+}
+
+function parseId(value: string | undefined): number {
+  if (!value || !/^\d+$/.test(value)) throw new UsageError("ID must be a positive integer");
+  const id = Number(value);
+  if (!Number.isSafeInteger(id) || id < 1) throw new UsageError("ID must be a positive integer");
+  return id;
+}
+
+function options(args: string[], allowed: string[]): Map<string, string> {
+  const parsed = new Map<string, string>();
+  for (let index = 0; index < args.length; index += 2) {
+    const flag = args[index];
+    const value = args[index + 1];
+    if (!allowed.includes(flag) || value === undefined || value.startsWith("--") || parsed.has(flag)) {
+      throw new UsageError(`Invalid option: ${flag ?? ""}`.trim());
+    }
+    parsed.set(flag, value);
+  }
+  return parsed;
+}
+
+export async function run(args: string[], file = process.env.TASKBOARD_FILE || resolve(".taskboard.json")): Promise<unknown> {
+  const [command, ...rest] = args;
+  if (!command) throw new UsageError("Missing command");
+  const database = await loadDatabase(file);
+
+  if (command === "add") {
+    const parsed = options(rest, ["--title", "--tags", "--due"]);
+    const title = parsed.get("--title")?.trim();
+    if (!title) throw new UsageError("Title must not be empty");
+    const due = parsed.get("--due");
+    if (due && !isDate(due)) throw new UsageError("Due date must be YYYY-MM-DD");
+    const task: Task = { id: database.nextId++, title, tags: normalizeTags(parsed.get("--tags") || ""), status: "open", createdAt: new Date().toISOString() };
+    if (due) task.due = due;
+    database.tasks.push(task);
+    await saveDatabase(file, database);
+    return task;
+  }
+
+  if (command === "list") {
+    const parsed = options(rest, ["--status", "--tag", "--overdue"]);
+    const status = parsed.get("--status");
+    const tag = parsed.get("--tag")?.trim().toLowerCase();
+    const overdue = parsed.get("--overdue");
+    if (status && status !== "open" && status !== "done") throw new UsageError("Status must be open or done");
+    if (overdue && !isDate(overdue)) throw new UsageError("Overdue date must be YYYY-MM-DD");
+    return database.tasks.filter((task) => (!status || task.status === status) && (!tag || task.tags.includes(tag)) && (!overdue || (task.status === "open" && !!task.due && task.due < overdue))).sort((a, b) => a.id - b.id);
+  }
+
+  if (command === "done" || command === "delete") {
+    if (rest.length !== 1) throw new UsageError(`Usage: ${command} ID`);
+    const id = parseId(rest[0]);
+    const index = database.tasks.findIndex((task) => task.id === id);
+    if (index === -1) throw new UsageError(`Task ${id} not found`);
+    if (command === "delete") {
+      const [deleted] = database.tasks.splice(index, 1);
+      await saveDatabase(file, database);
+      return deleted;
+    }
+    const task = database.tasks[index];
+    if (task.status === "open") {
+      task.status = "done";
+      task.completedAt = new Date().toISOString();
+      await saveDatabase(file, database);
+    }
+    return task;
+  }
+
+  if (command === "stats") {
+    if (rest.length) throw new UsageError("Usage: stats");
+    const open = database.tasks.filter((task) => task.status === "open").length;
+    const done = database.tasks.length - open;
+    const overdue = database.tasks.filter((task) => task.status === "open" && !!task.due && task.due < today()).length;
+    return { total: database.tasks.length, open, done, overdue };
+  }
+  throw new UsageError(`Unknown command: ${command}`);
+}
+
+if (import.meta.main) {
+  try {
+    console.log(JSON.stringify(await run(Bun.argv.slice(2))));
+  } catch (error) {
+    const message = error instanceof Error ? error.message : "Unexpected error";
+    console.error(message);
+    console.log(JSON.stringify({ error: message }));
+    process.exitCode = 1;
+  }
