+import { afterEach, describe, expect, test } from "bun:test";
+import { existsSync } from "node:fs";
+import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { run } from "../src/cli";
+
+const directories: string[] = [];
+async function databasePath(): Promise<string> {
+  const directory = await mkdtemp(join(tmpdir(), "taskboard-"));
+  directories.push(directory);
+  return join(directory, "board.json");
+}
+afterEach(async () => Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true }))));
+
+describe("taskboard", () => {
+  test("persists, filters, completes, and reports stats", async () => {
+    const file = await databasePath();
+    const first = await run(["add", "--title", " First ", "--tags", "Work, work, urgent", "--due", "2026-01-01"], file);
+    const second = await run(["add", "--title", "Second"], file);
+    expect(first).toMatchObject({ id: 1, title: "First", tags: ["work", "urgent"], status: "open" });
+    expect(second).toMatchObject({ id: 2 });
+    expect(await run(["list", "--tag", "WORK", "--overdue", "2026-02-01"], file)).toHaveLength(1);
+    const completed = await run(["done", "1"], file);
+    expect(completed).toMatchObject({ status: "done" });
+    expect(await run(["stats"], file)).toMatchObject({ total: 2, open: 1, done: 1, overdue: 0 });
+    expect(JSON.parse(await readFile(file, "utf8")).nextId).toBe(3);
+  });
+
+  test("rejects invalid input without replacing malformed data", async () => {
+    const file = await databasePath();
+    await expect(run(["add", "--title", "", "--due", "2026-02-30"], file)).rejects.toThrow("Title must not be empty");
+    await writeFile(file, "not json");
+    await expect(run(["list"], file)).rejects.toThrow("Malformed database");
+    expect(await readFile(file, "utf8")).toBe("not json");
+    expect(existsSync(`${file}.tmp`)).toBe(false);
+  });
+});

